use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let dishes = galley.menu.board();
    var i = 0;
    while i < dishes.len() {
        if i > 0 {
            io.write(text: ";")?;
        }
        match dishes.get(index: i) {
            Some(dish) => {
                galley.kitchen.serve(io: io, dish: dish)?;
            }
            None => {
                unit
            }
        }
        i = i + 1;
    }
    return Ok(unit);
}

use mill.stock;
use mill.rules;

pub fn lines() -> String {
    let inventory = mill.stock.inventory();
    var labels: List<String> = [];
    var i = 0;
    while i < inventory.len() {
        let plank = match inventory.get(index: i) {
            Some(p) => p,
            None => break,
        };
        if mill.rules.should_keep(plank: plank) {
            labels.push(item: mill.rules.render_label(plank: plank));
        }
        i = i + 1;
    }
    return labels.join(sep: ",");
}

use mill.stock;
