    let n = inventory.len();
    while i < n {
        match inventory.get(index: i) {
            Some(plank) => {
                if mill.rules.is_kept(plank: plank) {
                    labels.push(item: mill.rules.to_label(plank: plank));
                }
            }
            None => unit,
        }
        i = i + 1;
    }
    return labels.join(sep: ",");
}

use harbor.signal;

pub fn entries() -> String {
    var out = "";
    let all = harbor.signal.signals();
    var i = 0;
    while i < all.len() {
        if i > 0 {
            out = out.concat(other: ";");
        }
        let piece = match all.get(index: i) {
            Some(s) => match s {
                harbor.signal.Signal.Calm => "calm",
                harbor.signal.Signal.Gale(speed) => "gale:".concat(other: speed.to_text()),
                harbor.signal.Signal.Fog(word) => "fog:".concat(other: word),
            },
            None => "",
        };
        out = out.concat(other: piece);
        i = i + 1;
    }
    out
}

