use depot.locker;

pub fn report() -> String {
    var ax = depot.locker.new(label: "ax");
    ax = match depot.locker.stow(locker: ax, load: 12) {
        Ok(l) => l,
        Err(_) => ax,
    };
    ax = match depot.locker.stow(locker: ax, load: 9) {
        Ok(l) => l,
        Err(_) => ax,
    };

    var bay = depot.locker.new(label: "bay");
    bay = match depot.locker.stow(locker: bay, load: 30) {
        Ok(l) => l,
        Err(_) => bay,
    };
    bay = match depot.locker.stow(locker: bay, load: 25) {
        Ok(l) => l,
        Err(_) => bay,
    };

    var cod = depot.locker.new(label: "cod");
    cod = match depot.locker.stow(locker: cod, load: 5) {
        Ok(l) => l,
        Err(_) => cod,
    };

    let parts: List<String> = [
        ax.label.concat(other: "=").concat(other: ax.weight.to_text()),
        bay.label.concat(other: "=").concat(other: bay.weight.to_text()),
        cod.label.concat(other: "=").concat(other: cod.weight.to_text()),
    ];
    parts.join(sep: ",")
}

