use stable.herd;
use stable.ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let ponies = stable.herd.lineup();
    var entries: List<String> = [];
    var i = 0;
    while i < ponies.len() {
        let entry_text = match ponies.get(index: i) {
            Some(p) => {
                let fed = stable.herd.feed(pony: p, scoops: 3);
                stable.ledger.entry(pony: fed)
            }
            None => "",
        };
        entries.push(entry_text);
        i += 1;
    }
    io.write(text: entries.join(sep: ","))?;
    return Ok(unit);
}
